var SCOPERTE=[{t:"L'agopuntura auricolare accelera il recupero dopo la protesi di ginocchio, dice una metanalisi cinese",v:"Una network metanalisi di 24 trial randomizzati (1790 pazienti) mostra che le terapie sui punti auricolari — spesso combinate con la medicina tradizionale cinese — riducono il dolore nei primi giorni dopo la protesi totale di ginocchio e migliorano la funzione precoce, ma la certezza delle prove resta bassa o molto bassa: gli autori stessi la definiscono un riferimento preliminare, non una linea guida clinica.",pmid:'42764684',doi:'10.1155/prm/9277186',temi:["medicina tradizionale cinese","riabilitazione post-protesi","agopuntura"]},{t:"Un esoscheletro cinese legge cervello e muscoli insieme per capire quando vuoi camminare",v:"Un gruppo di Pechino ha combinato segnali elettroencefalografici ed elettromiografici per far scattare l'assistenza di un esoscheletro per arto inferiore più rapidamente e con più precisione rispetto ai due segnali usati da soli — ancora una prova di concetto su volontari sani, lontana dal paziente reale, ma è la stessa domanda di fondo dell'inibizione muscolare dopo un trauma al ginocchio: come il sistema nervoso decide, e a volte inganna, il movimento.",pmid:'42755609',doi:'10.3389/fnbot.2026.1914651',temi:["bioingegneria","interfaccia cervello-macchina","esoscheletro"]}];
var SOC={"1": {"video": "Hai appena pubblicato FIRM-P: un framework per ragionare sull'instabilità del legamento crociato anteriore in cinque passaggi. Prima descrivi il ginocchio su quattro assi — come si muove, come si sente il paziente, cosa dice la risonanza, quanto è lasco al test strumentale. Poi verifichi che i quattro segnali raccontino la stessa storia; se non lo fanno, non decidi subito, controlli meglio. L'inibizione muscolare artrogena entra qui: può far sembrare instabile un ginocchio che non lo è, o nascondere un'instabilità vera dietro un quadricipite che non si attiva. Solo alla fine, quando il ginocchio è davvero classificato, entra il contesto del paziente — quanto gli serve la stabilità per la sua vita. È un framework concettuale, livello cinque, non ancora validato: lo dichiari tu stesso nell'articolo."}};
var SOCV={"1": {"video": {"chir": ["Hai pubblicato FIRM-P su Journal of Experimental Orthopaedics, con Matteo Denti e Marc Barrera Uso: un framework concettuale che separa il fenotipo di instabilità del legamento crociato anteriore dal contesto clinico del paziente. Quattro domini — funzionale, individuale, radiologico, meccanico — descrivono il ginocchio prima ancora di pensare al trattamento.", "Hai pubblicato FIRM-P su Journal of Experimental Orthopaedics, con Matteo Denti e Marc Barrera Uso: un framework concettuale che separa il fenotipo di instabilità del legamento crociato anteriore dal contesto clinico del paziente. Quattro domini — funzionale, individuale, radiologico, meccanico — descrivono il ginocchio prima ancora di pensare al trattamento. Un ciclo di verifica gestisce i pattern discordanti invece di forzare una decisione: se funzione e laxità strumentale non raccontano la stessa storia, il passo successivo è controllare meglio, non scegliere. L'inibizione muscolare artrogena entra come modificatore trasversale — non un quinto pilastro — perché può amplificare l'instabilità funzionale e percepita anche a ginocchio strutturalmente integro, o coesistere con un'insufficienza vera del legamento.", "Hai pubblicato FIRM-P su Journal of Experimental Orthopaedics, con Matteo Denti e Marc Barrera Uso: un framework concettuale che separa il fenotipo di instabilità del legamento crociato anteriore dal contesto clinico del paziente. Quattro domini — funzionale, individuale, radiologico, meccanico — descrivono il ginocchio prima ancora di pensare al trattamento. Un ciclo di verifica gestisce i pattern discordanti invece di forzare una decisione: se funzione e laxità strumentale non raccontano la stessa storia, il passo successivo è controllare meglio, non scegliere. L'inibizione muscolare artrogena entra come modificatore trasversale — non un quinto pilastro — perché può amplificare l'instabilità funzionale e percepita anche a ginocchio strutturalmente integro, o coesistere con un'insufficienza vera del legamento. Solo dopo la verifica il ginocchio viene classificato in una delle quattro classi finali — dal fenotipo a bassa instabilità fino all'instabilità conclamata — e solo allora entra il contesto del paziente, mai prima. Livello di evidenza V: framework proposto, non ancora validato per contenuto, affidabilità o derivazione prospettica — un punto di partenza per il lavoro di consenso che deve seguire, non un punteggio pronto all'uso."], "misto": ["È uscito il tuo lavoro FIRM-P: uno schema per ragionare sull'instabilità del ginocchio dopo una lesione del legamento crociato anteriore, pensato per essere capito da chi opera, da chi fa la riabilitazione e da chi segue il paziente ogni giorno.", "È uscito il tuo lavoro FIRM-P: uno schema per ragionare sull'instabilità del ginocchio dopo una lesione del legamento crociato anteriore, pensato per essere capito da chi opera, da chi fa la riabilitazione e da chi segue il paziente ogni giorno. L'idea di fondo: prima si descrive come si comporta il ginocchio — come si muove, come si sente il paziente, cosa mostra la risonanza, quanto è lasco al test in ambulatorio — e solo dopo, se questi quattro segnali raccontano storie diverse, si va a verificare meglio invece di decidere subito. Un fattore spesso dimenticato, l'inibizione del quadricipite dopo il trauma, viene inserito come qualcosa che può alterare la lettura degli altri segnali, non come un quinto elemento a sé.", "È uscito il tuo lavoro FIRM-P: uno schema per ragionare sull'instabilità del ginocchio dopo una lesione del legamento crociato anteriore, pensato per essere capito da chi opera, da chi fa la riabilitazione e da chi segue il paziente ogni giorno. L'idea di fondo: prima si descrive come si comporta il ginocchio — come si muove, come si sente il paziente, cosa mostra la risonanza, quanto è lasco al test in ambulatorio — e solo dopo, se questi quattro segnali raccontano storie diverse, si va a verificare meglio invece di decidere subito. Un fattore spesso dimenticato, l'inibizione del quadricipite dopo il trauma, viene inserito come qualcosa che può alterare la lettura degli altri segnali, non come un quinto elemento a sé. Solo alla fine, quando il quadro è chiaro, entra in gioco quanto serve la stabilità per la vita di quel paziente specifico. È uno schema di ragionamento, non un punteggio già pronto: lo stesso autore lo definisce un primo passo che va ancora validato, non una risposta definitiva."], "pazienti": ["Il tuo chirurgo ha appena pubblicato un lavoro scientifico su come si valuta l'instabilità del ginocchio dopo un infortunio al legamento crociato anteriore.", "Il tuo chirurgo ha appena pubblicato un lavoro scientifico su come si valuta l'instabilità del ginocchio dopo un infortunio al legamento crociato anteriore. L'idea è semplice da capire anche se il metodo è tecnico: prima si guarda il ginocchio da più angolazioni — come si muove, come si sente il paziente stesso, cosa dice la risonanza, quanto è instabile a un test in ambulatorio — invece di basarsi su un solo segnale. Se questi segnali non concordano fra loro, il passo giusto è controllare meglio, non decidere in fretta.", "Il tuo chirurgo ha appena pubblicato un lavoro scientifico su come si valuta l'instabilità del ginocchio dopo un infortunio al legamento crociato anteriore. L'idea è semplice da capire anche se il metodo è tecnico: prima si guarda il ginocchio da più angolazioni — come si muove, come si sente il paziente stesso, cosa dice la risonanza, quanto è instabile a un test in ambulatorio — invece di basarsi su un solo segnale. Se questi segnali non concordano fra loro, il passo giusto è controllare meglio, non decidere in fretta. Il metodo tiene anche conto del fatto che dopo un trauma il muscolo della coscia può 'spegnersi' temporaneamente, facendo sembrare il ginocchio più instabile di quanto sia davvero — un dettaglio che può cambiare i tempi di un eventuale intervento. È una proposta scientifica nuova, non ancora testata su larga scala: lo dice chiaramente lo stesso studio."]}, "linkedin": {"chir": ["FIRM-P (Giunchi, Denti, Barrera Uso — J Exp Orthop): framework concettuale che separa il fenotipo di instabilità del LCA (F-funzionale, I-individuale, R-radiologico, M-meccanico) dal contesto del paziente (P), con l'AMI integrata come modificatore trasversale, non come quinto dominio.", "Regola di classificazione esplicita: 16 pattern FIRM mappano su 4 fenotipi verificati (basso-instabilità/non-LCA, occulto/associato, LCA-deficiente compensato, instabilità conclamata). Ciclo di verifica per i pattern discordanti prima di qualunque decisione terapeutica; matrice operativa a 32 scenari e prototipo HTML interattivo in supplemento.", "Livello V, opinione di esperti: nessuna validazione di contenuto, affidabilità inter-osservatore o derivazione prospettica finora. Gli autori lo definiscono un'architettura concettuale su cui costruire consenso, reliability e validazione — non un punteggio pronto all'uso."], "misto": ["Ho pubblicato FIRM-P: un metodo per ragionare sull'instabilità del ginocchio dopo una lesione del crociato anteriore, che separa come si comporta il ginocchio da quanto quella instabilità conta per il singolo paziente.", "Quattro modi di guardare il ginocchio — come si muove, come si sente, cosa mostra l'imaging, quanto è lasco a un test oggettivo — vengono prima verificati per coerenza, e solo dopo interpretati alla luce delle esigenze reali del paziente. L'inibizione muscolare dopo il trauma è trattata come un fattore che può alterare la lettura, non come un elemento a sé.", "È un framework di ragionamento clinico, non un punteggio pronto: livello di evidenza V, ancora da validare. Il valore, per ora, è mettere ordine in una decisione che spesso si prende su un solo segnale isolato."], "pazienti": ["Ho pubblicato un lavoro scientifico su come valutare, in modo più completo, l'instabilità del ginocchio dopo un infortunio al legamento crociato anteriore.", "L'idea: guardare il ginocchio da più punti di vista — come si muove, come lo sente il paziente, cosa dice la risonanza, quanto è instabile a un test in ambulatorio — prima di decidere qualunque cosa, e tenere conto che dopo un trauma il muscolo della coscia può temporaneamente 'spegnersi', facendo sembrare il ginocchio più instabile di quanto sia.", "È una proposta scientifica nuova, non ancora validata su larga scala — un primo passo, non una risposta definitiva."]}, "instagram": {"chir": ["🧠 Pubblicato FIRM-P (J Exp Orthop): framework che separa il fenotipo di instabilità del LCA dal contesto del paziente.", "🧠 Pubblicato FIRM-P (J Exp Orthop): framework che separa il fenotipo di instabilità del LCA dal contesto del paziente. Quattro domini (F-I-R-M) verificati per coerenza, poi il contesto (P). L'AMI entra come modificatore trasversale, non un quinto pilastro.", "🧠 Pubblicato FIRM-P (J Exp Orthop): framework che separa il fenotipo di instabilità del LCA dal contesto del paziente. Quattro domini (F-I-R-M) verificati per coerenza, poi il contesto (P). L'AMI entra come modificatore trasversale, non un quinto pilastro. Livello V: proposta concettuale, non ancora validata — il punto di partenza per il consenso che deve seguire."], "misto": ["🧠 Il mio nuovo lavoro scientifico: uno schema per ragionare sull'instabilità del ginocchio dopo il crociato anteriore.", "🧠 Il mio nuovo lavoro scientifico: uno schema per ragionare sull'instabilità del ginocchio dopo il crociato anteriore. Prima si guarda come si comporta il ginocchio da più lati, poi si verificano le discordanze, solo alla fine entra il paziente.", "🧠 Il mio nuovo lavoro scientifico: uno schema per ragionare sull'instabilità del ginocchio dopo il crociato anteriore. Prima si guarda come si comporta il ginocchio da più lati, poi si verificano le discordanze, solo alla fine entra il paziente. Livello di evidenza V: un metodo di ragionamento, non ancora un punteggio validato."], "pazienti": ["🦵 Ho pubblicato un lavoro scientifico su come valutare meglio l'instabilità del ginocchio dopo un infortunio al crociato anteriore.", "🦵 Ho pubblicato un lavoro scientifico su come valutare meglio l'instabilità del ginocchio dopo un infortunio al crociato anteriore. L'idea: guardare il ginocchio da più angolazioni prima di decidere, tenendo conto che il muscolo della coscia può 'spegnersi' temporaneamente dopo il trauma.", "🦵 Ho pubblicato un lavoro scientifico su come valutare meglio l'instabilità del ginocchio dopo un infortunio al crociato anteriore. L'idea: guardare il ginocchio da più angolazioni prima di decidere, tenendo conto che il muscolo della coscia può 'spegnersi' temporaneamente dopo il trauma. Una proposta scientifica nuova, ancora da validare su larga scala."]}, "reel": {"chir": ["[Testo a schermo: FIRM-P] Framework per il fenotipo di instabilità del LCA.", "[Testo a schermo: FIRM-P] Framework per il fenotipo di instabilità del LCA. [Testo: 4 DOMINI + CONTESTO] F-I-R-M verificati, poi il paziente.", "[Testo a schermo: FIRM-P] Framework per il fenotipo di instabilità del LCA. [Testo: 4 DOMINI + CONTESTO] F-I-R-M verificati, poi il paziente. [Testo: LIVELLO V] Proposta concettuale, non ancora validata."], "misto": ["[Testo a schermo: UN NUOVO MODO DI VALUTARE IL GINOCCHIO] Dopo il crociato anteriore.", "[Testo a schermo: UN NUOVO MODO DI VALUTARE IL GINOCCHIO] Dopo il crociato anteriore. [Testo: PRIMA IL GINOCCHIO, POI IL PAZIENTE] Verifica prima di decidere.", "[Testo a schermo: UN NUOVO MODO DI VALUTARE IL GINOCCHIO] Dopo il crociato anteriore. [Testo: PRIMA IL GINOCCHIO, POI IL PAZIENTE] Verifica prima di decidere. [Testo: ANCORA DA VALIDARE] Un metodo di ragionamento, non un punteggio pronto."], "pazienti": ["[Testo a schermo: IL MIO NUOVO LAVORO SCIENTIFICO] Su come valutare il ginocchio dopo il crociato anteriore.", "[Testo a schermo: IL MIO NUOVO LAVORO SCIENTIFICO] Su come valutare il ginocchio dopo il crociato anteriore. [Testo: PIÙ ANGOLAZIONI, PRIMA DI DECIDERE] Anche il muscolo che si 'spegne' dopo il trauma.", "[Testo a schermo: IL MIO NUOVO LAVORO SCIENTIFICO] Su come valutare il ginocchio dopo il crociato anteriore. [Testo: PIÙ ANGOLAZIONI, PRIMA DI DECIDERE] Anche il muscolo che si 'spegne' dopo il trauma. [Testo: PROPOSTA NUOVA, ANCORA DA VALIDARE]"]}}};
